import json, sys

def get_text(content):
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for c in content:
            if isinstance(c, dict):
                if c.get('type') == 'text':
                    parts.append(c.get('text',''))
                elif c.get('type') == 'tool_use':
                    parts.append(f"[TOOL_USE {c.get('name')} input={json.dumps(c.get('input'))[:300]}]")
                elif c.get('type') == 'tool_result':
                    cc = c.get('content')
                    if isinstance(cc, list):
                        cc = ' '.join(x.get('text','') for x in cc if isinstance(x,dict))
                    parts.append(f"[TOOL_RESULT err={c.get('is_error')} {str(cc)[:300]}]")
            else:
                parts.append(str(c)[:200])
        return ' '.join(parts)
    return str(content)[:200]

path = sys.argv[1]
with open(path) as f:
    for line in f:
        line=line.strip()
        if not line: continue
        try:
            d = json.loads(line)
        except Exception as e:
            print("PARSE ERROR", e)
            continue
        t = d.get('type')
        ts = d.get('timestamp')
        if t == 'queue-operation':
            print(f"{ts} QUEUE-{d.get('operation')}: {str(d.get('content'))[:300]}")
            continue
        msg = d.get('message')
        if msg:
            role = msg.get('role')
            content = msg.get('content')
            text = get_text(content)
            usage = msg.get('usage')
            u = ''
            if usage:
                u = f" [tok in={usage.get('input_tokens')} out={usage.get('output_tokens')}]"
            print(f"{ts} {role}{u}: {text[:500]}")
            continue
        attach = d.get('attachment')
        if attach:
            print(f"{ts} ATTACH type={attach.get('type')} hook={attach.get('hookName')}: {str(attach.get('content'))[:200]}")
            continue
        print(f"{ts} OTHER: {json.dumps(d)[:300]}")

