import json, sys
from datetime import datetime

def parse_ts(ts):
    if not ts: return None
    try:
        return datetime.fromisoformat(ts.replace('Z','+00:00'))
    except Exception:
        return None

def trunc(s, n=300):
    if s is None: return ""
    s = str(s)
    return s if len(s) <= n else s[:n] + "...[%d chars]" % len(s)

def main(path, gap_threshold=60):
    entries = []
    with open(path) as f:
        for i, line in enumerate(f):
            line = line.strip()
            if not line: continue
            try:
                e = json.loads(line)
            except Exception:
                continue
            entries.append((i, e))

    print("=== REAL USER TEXT TURNS ===")
    for i, e in entries:
        msg = e.get('message')
        if not isinstance(msg, dict): continue
        if msg.get('role') != 'user': continue
        content = msg.get('content')
        if isinstance(content, str) and content.strip():
            print(f"[{i}] ts={e.get('timestamp')} USER: {trunc(content, 500)!r}")
        elif isinstance(content, list):
            for c in content:
                if isinstance(c, dict) and c.get('type') == 'text' and c.get('text','').strip():
                    print(f"[{i}] ts={e.get('timestamp')} USER: {trunc(c.get('text'), 500)!r}")

    print("\n=== ASK_USER_QUESTION CALLS ===")
    for i, e in entries:
        msg = e.get('message')
        if not isinstance(msg, dict): continue
        content = msg.get('content')
        if isinstance(content, list):
            for c in content:
                if isinstance(c, dict) and c.get('type') == 'tool_use' and 'AskUserQuestion' in str(c.get('name','')):
                    print(f"[{i}] ts={e.get('timestamp')} ASK: {trunc(json.dumps(c.get('input',{})), 500)}")
                if isinstance(c, dict) and c.get('type') == 'tool_result' and False:
                    pass

    print("\n=== TIMESTAMP GAPS > %ds ===" % gap_threshold)
    prev_ts = None
    prev_i = None
    for i, e in entries:
        ts = parse_ts(e.get('timestamp'))
        if ts is None:
            continue
        if prev_ts is not None:
            delta = (ts - prev_ts).total_seconds()
            if delta > gap_threshold:
                # describe what's at prev and current
                msg = e.get('message')
                desc = e.get('type')
                if isinstance(msg, dict):
                    content = msg.get('content')
                    if isinstance(content, list) and content:
                        c0 = content[0]
                        if isinstance(c0, dict):
                            desc = c0.get('type')
                            if desc == 'tool_use':
                                desc += ':' + str(c0.get('name'))
                print(f"GAP {delta:.1f}s between [{prev_i}] and [{i}] ({e.get('timestamp')}) next={desc}")
        prev_ts = ts
        prev_i = i

    print("\n=== SESSION SPAN ===")
    tss = [parse_ts(e.get('timestamp')) for _, e in entries if parse_ts(e.get('timestamp'))]
    if tss:
        print(f"start={min(tss)} end={max(tss)} total={ (max(tss)-min(tss)).total_seconds()/60:.1f} min, n_entries={len(entries)}")

if __name__ == '__main__':
    path = sys.argv[1]
    gap = int(sys.argv[2]) if len(sys.argv) > 2 else 60
    main(path, gap)

