8	
9	// The write-surface gate for the growth lifecycle's two CAPTURE runs — extract
10	// and dedup. Their docs bound every edit to the repo's own local packs, and
11	// extract's PR auto-merges with no human review, so the boundary needs a
12	// machine guarantee, not a prose request: when a branch carries one of those
13	// runs' pinned commit subjects, every path it touches — added, modified, or
14	// deleted — must sit under .claudinite/local/packs/ (the legacy
15	// .claudinite/local_packs/ accepted during the rename window).
16	//
17	// The trigger is the run's whole pinned title, NOT the bare "Claudinite growth:"
18	// prefix the whole lifecycle shares, because a sibling run under that prefix has a
19	// wider write surface by design, and keying on the prefix would red it. A run whose
20	// title this list doesn't carry is simply not this rule's business.
21	//
22	// A capture run marks ITSELF via that title, so this rule self-gates and runs
23	// everywhere the pack is active: at the session Stop hook (work scope), and as
24	// a CLI on every PR in the canon repo's CI.
25	//
26	// Local packs live under either root during the rename transition; git emits
27	// '/'-separated paths, so the platform-joined constants are normalized.
28	const LOCAL_ROOTS = [LOCAL_PACKS_SUBDIR, LEGACY_LOCAL_PACKS_SUBDIR]
29	  .map((s) => `${s.split(sep).join('/')}/`);
30	
31	// The capture runs, by the exact titles their task docs pin. `conversation
32	// extract` is the pre-merge title of extract's conversation half, still in use
33	// wherever a consumer mounts a canon older than the one-task merge.
34	const CAPTURE_RUN = /^Claudinite growth: (?:extract lessons|conversation extract|dedup\b)/;
35	
36	const inSurface = (p) => LOCAL_ROOTS.some((root) => p.startsWith(root));
37	
38	const rule = {
39	  id: 'growth-write-scope',
40	  severity: 'blocking',
41	  scope: 'work',
42	  doc: 'packs/claudinite-growth/README.md',
43	  description: 'A growth capture run (extract, dedup) writes only the repo\'s own local packs',
44	  why: 'extract auto-merges its PR with no human review and dedup runs unattended; a capture run improves the repo\'s packs, so a write outside .claudinite/local/packs/ — the canon it prunes against, or the project\'s own code — escapes the review-by-blast-radius boundary the growth lifecycle is built on',
45	
46	  run(work) {
