import { sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { realpathSync } from 'node:fs';
import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { runRule } from '../../../engine/checks/helpers/work.mjs';
import { buildContext } from '../../../engine/checks/helpers/repo-context.mjs';
import { LOCAL_PACKS_SUBDIR, LEGACY_LOCAL_PACKS_SUBDIR } from '../../../engine/pack_loader/pack-registry.mjs';

// The write-surface gate for the growth lifecycle's two CAPTURE runs — extract
// and dedup. Their docs bound every edit to the repo's own local packs, and
// extract's PR auto-merges with no human review, so the boundary needs a
// machine guarantee, not a prose request: when a branch carries one of those
// runs' pinned commit subjects, every path it touches — added, modified, or
// deleted — must sit under .claudinite/local/packs/ (the legacy
// .claudinite/local_packs/ accepted during the rename window).
//
// The trigger is the run's whole pinned title, NOT the bare "Claudinite growth:"
// prefix the whole lifecycle shares, because a sibling run under that prefix has a
// wider write surface by design, and keying on the prefix would red it. A run whose
// title this list doesn't carry is simply not this rule's business.
//
// A capture run marks ITSELF via that title, so this rule self-gates and runs
// everywhere the pack is active: at the session Stop hook (work scope), and as
// a CLI on every PR in the canon repo's CI.
//
// Local packs live under either root during the rename transition; git emits
// '/'-separated paths, so the platform-joined constants are normalized.
const LOCAL_ROOTS = [LOCAL_PACKS_SUBDIR, LEGACY_LOCAL_PACKS_SUBDIR]
  .map((s) => `${s.split(sep).join('/')}/`);

// The capture runs, by the exact titles their task docs pin. `conversation
// extract` is the pre-merge title of extract's conversation half, still in use
// wherever a consumer mounts a canon older than the one-task merge.
const CAPTURE_RUN = /^Claudinite growth: (?:extract lessons|conversation extract|dedup\b)/;

const inSurface = (p) => LOCAL_ROOTS.some((root) => p.startsWith(root));

const rule = {
  id: 'growth-write-scope',
  severity: 'blocking',
  scope: 'work',
  doc: 'packs/claudinite-growth/README.md',
  description: 'A growth capture run (extract, dedup) writes only the repo\'s own local packs',
  why: 'extract auto-merges its PR with no human review and dedup runs unattended; a capture run improves the repo\'s packs, so a write outside .claudinite/local/packs/ — the canon it prunes against, or the project\'s own code — escapes the review-by-blast-radius boundary the growth lifecycle is built on',

  run(work) {
    if (work.onDefaultBranch()) return [];
    if (!work.commits.some((m) => CAPTURE_RUN.test(m))) return [];
    const touched = [...new Set([...work.changedFiles, ...work.deleted])];
    return touched
      .filter((p) => !inSurface(p))
      .sort()
      .map((p) => finding(rule, {
        file: p,
        what: `a growth capture run touched ${p}, outside ${LOCAL_ROOTS[0]}`,
        fix: 'a capture run improves the repo\'s packs, never the canon or the project\'s code — keep the whole write surface inside the local packs; a site-tied lesson lands as the owning pack\'s entry naming the site, and lifting one into the canon is the promote stage\'s job',
      }));
  },
};

export default rule;

// CLI body — a CI gate runs this on every PR (self-gating, ~nothing on a branch
// that is not a capture run):
// `node .claudinite/shared/packs/claudinite-growth/workRules/growth-write-scope.mjs [root]`.
//   exit 0 — not a capture run, or every touched path is under the local packs
//   exit 1 — a capture run touched a path outside the local packs
export function runCli(root = process.cwd()) {
  const ctx = buildContext({ root, mode: 'changed' });
  if (!ctx.mergeBase) {
    // Without a merge-base there is no diff — and no branch commits — to read,
    // so there is nothing to self-gate on. This step runs on EVERY PR, so
    // refusing here would fail every history-less checkout on an ordinary one;
    // the Stop-hook run still covers the session side.
    console.log('growth-write-scope: no merge-base with the base branch — nothing to scope.');
    process.exit(0);
  }
  const findings = runRule(rule, ctx);
  if (findings.length) {
    console.error(`growth-write-scope: FAIL — a growth capture run may write only under ${LOCAL_ROOTS[0]}, but this branch also touches ${findings.length} path(s):`);
    for (const f of findings) console.error(`  - ${f.file}`);
    console.error('\nA capture run improves the repo\'s packs, never the canon or the project\'s code — keep the whole write surface inside the local packs.');
    process.exit(1);
  }
  console.log('growth-write-scope: OK — not a capture run, or every touched path is under the local packs.');
}

if (process.argv[1] && realpathSync(process.argv[1]) === fileURLToPath(import.meta.url)) {
  runCli(process.argv[2] || process.cwd());
}

// claudinite-growth task: growth-extract — the growth lifecycle's CAPTURE
// stage (per-project-scheduling DESIGN §6). ONE task over BOTH lesson sources:
// it runs the extract-from-activity skill over the window's commits/PRs/issues
// and the extract-from-conversations skill over the captured conversation logs,
// then runs prose-to-checks over what it just wrote to see whether any of it
// upgrades to a check — and lands the whole run through a single PR delivered
// per the repo's delivery settings (task.md → the shared deliver-pr.md
// procedure). Worker: task.md.
//
// The two halves were separate tasks (growth-extract + conversation-extract)
// firing at the same daily anchor, each opening its own PR against the same local
// packs on the same night. They shared the lesson bar, the promotion ladder, the
// dedup surface and the landing mechanics, so splitting them bought nothing and
// cost a second opus dispatch, a second PR, and two runs deduping against a
// corpus the other one was concurrently writing. One task, two source skills.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'growth-extract',
  frequency: 'daily',
  // The ordering, declared (tasks-dispatch DESIGN §9) — and now the ONLY thing carrying it, since
  // the staggered anchor hours retired with the twice-daily cron (§17.1). This task reads a mount
  // `claudinite-lifecycle/update` converges, so it yields while that task's item is live this
  // cycle and runs the moment it converges — or rolls. The offset only ever implied this; the
  // declaration enforces it.
  schedule_after: ['claudinite-lifecycle/update'],
  precondition_signals: ['commits', 'prs', 'issues'],
  agent_model: 'opus',                   // generalizing/curating lessons is the heaviest judgment, and the default delivery lands the PR with no human review
  expected_outcome: 'pr',
  // Lessons land in the repo's own local packs — prose, and the checks the in-run
  // upgrade pass produces (this pack's merge-rules.json declares both classes).
  automerge: ['claudinite-local-pack-md-changes', 'claudinite-local-pack-check-changes'],
  agent_instructions: 'task.md',
  agent_execution_timeout: 2700,            // two source passes plus the prose-to-checks upgrade — generous bound, extreme protection

  // ONE reason to run: a SUBSTANTIVE default-branch change. A bot bump / [skip ci] /
  // nightly-baselining commit advancing main is not a lesson to extract, and neither
  // is a commit that touched nothing outside `.claudinite/` — this lifecycle's own
  // landed output, which would otherwise re-arm it every night and keep a quiet repo
  // firing forever. `commits.substantiveChange` already applies that classification.
  // It arms the activity half AND means a fresh capture now sits on the logs branch,
  // so the conversation half runs too.
  //
  // There WAS a second arm — a log actually past retention, which existed only so
  // the retention prune still fired on a repo gone quiet. The prune is its own
  // agentless task now (../logs-prune/), so that arm left with it and this opus
  // dispatch no longer happens on nights with nothing to extract.
  //
  // The activity half is scoped by the substantive shas + touched PR/issue numbers
  // passed as binding scope — INCLUDING the PRs merged during the window, whose
  // review discussion is usually its richest lesson source. Context is binding
  // scope and task.md forbids widening past it, so a merged PR the precondition
  // does not name is unreadable to the worker.
  precondition(signals) {
    const commits = signals.commits ?? {};
    if (commits.substantiveChange !== true) {
      return { run: false, reason: 'no substantive default-branch change in the window — nothing to extract' };
    }

    const shas = (commits.list ?? []).filter((c) => c.substantive).map((c) => c.sha.slice(0, 7));
    const prs = signals.prs?.touched ?? [];
    const merged = (signals.prs?.merged ?? []).map((p) => p.number);
    const issues = signals.issues?.touched ?? [];

    const context = [`Activity half IS in scope: the ${shas.length} substantive commit(s) in the window — ${shas.join(', ')}.`];
    if (merged.length) context.push(`PRs merged in the window — read each one's diff and its review discussion: ${merged.map((n) => `#${n}`).join(', ')}.`);
    if (prs.length) context.push(`PRs touched in the window: ${prs.map((n) => `#${n}`).join(', ')}.`);
    if (issues.length) context.push(`Issues touched in the window: ${issues.map((n) => `#${n}`).join(', ')}.`);
    context.push('Conversation half IS in scope: a substantive merge means fresh captures on origin/conversation-logs — run the fresh pass over the recent window.');

    return { run: true, reason: `${shas.length} substantive commit(s) in the window`, context };
  },
};

